SELECT qryTKClose_A.CaseID, qryTKClose_A.FileNumber, qryTKClose_A.Name, qryTKClose_A.Orig_Atty, qryTKClose_A.HandlingAtty_Case, qryTKClose_A.SumOfAdvancedAR, qryTKClose_A.CostHold, qryTKClose_A.SumOfUnclearedDeposits, qryTKClose_A.Balance, qryTKClose_A.SumOfUncashedChecks, [Balance]-Nz([SumOfUnclearedDeposits],0) AS AvailBalance, qryTKClose_A.SumOfTotal, [Balance]+Nz([SumOfUncashedChecks],0)-Nz([SumOfUnclearedDeposits],0) AS BankBalance, qryTKClose_A.IANumber, qryTKClose_A.Bill_ID, qryTKClose_A.Retainer, qryTKClose_A.RetainerReimb, qryTKClose_A.RetReimbAmount, qryTKClose_A.MaxOfMatterID, qryTKClose_A.AROutstandingBalance, qryTKClose_A.AdvanceCostBalance, qryTKClose_A.AdvLegalFeeBalance, qryTKClose_A.CostExpendedBalance, qryTKClose_A.Case_Letter, qryTKClose_A.Fixed
FROM qryTKClose_A
WHERE (((qryTKClose_A.IANumber) Is Not Null) AND ((qryTKClose_A.Bill_ID) Is Not Null) AND ((qryTKClose_A.Case_Letter)<>"P" And (qryTKClose_A.Case_Letter)<>"T" And (qryTKClose_A.Case_Letter)<>"B") AND ((qryTKClose_A.Fixed)=False))
ORDER BY qryTKClose_A.Name;